INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷102·隐帝本纪·乾祐二年六月杨信奏报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/77bbd325fb94c5e1dfb482972cb6de0b03c635d5/content/books/zizhi-tongjian/vol-289/year-0950/part-02/sources/library/jiuwudaishi-102-yang-xin-father/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年六月杨信奏报，段落 jiu-wudaishi-205deb4a7860-p002475；已核上下文及传主，纸本及异文待核。", "id": "77a41964-67e5-5f46-8bb9-5d1004412bd5"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/77bbd325fb94c5e1dfb482972cb6de0b03c635d5/content/books/zizhi-tongjian/vol-289/year-0950/part-02/sources/library/jiuwudaishi-103-february-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年二月，段落 jiu-wudaishi-205deb4a7860-p002484；已核上下文及传主，纸本及异文待核。", "id": "1ec74a84-7256-5ef4-abe2-319c7ae8096c"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/77bbd325fb94c5e1dfb482972cb6de0b03c635d5/content/books/zizhi-tongjian/vol-289/year-0950/part-02/sources/library/jiuwudaishi-103-march-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年三月，段落 jiu-wudaishi-205deb4a7860-p002485；已核上下文及传主，纸本及异文待核。", "id": "ea95ea08-6ca9-55dc-8861-b133e12aa0b9"}, {"title": "旧五代史·卷105·刘审交传·去世与汝州民众追念", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/77bbd325fb94c5e1dfb482972cb6de0b03c635d5/content/books/zizhi-tongjian/vol-289/year-0950/part-02/sources/library/jiuwudaishi-105-liu-shenjiao-death/source.txt", "note": "《旧五代史》卷105·刘审交传·去世与汝州民众追念，段落 jiu-wudaishi-205deb4a7860-p002528；已核上下文及传主，纸本及异文待核。", "id": "8b312c1d-ee9a-5505-869c-5c9c3b8f092a"}, {"title": "资治通鉴·卷289·乾祐三年·正月、二月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/aecd425b6a5c2b61245e92470190e94829f2d494/content/books/zizhi-tongjian/vol-289/year-0950/part-01/sources/library/tongjian-289-950-opening/source.txt", "note": "《资治通鉴》卷289·乾祐三年·正月、二月及追述，段落 zizhi-tongjian-a63549944a71-p003427；已核上下文及传主，纸本及异文待核。", "id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"title": "新五代史·卷62·南唐世家·陈诲后续活动校核", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf9e990066dba1dacd217dcd86a7c0d28b93b91c/content/books/zizhi-tongjian/vol-285/year-0946/part-04/sources/library/xinwudaishi-062-chen-hui-later/source.txt", "note": "《新五代史》卷62·南唐世家·八年陈诲参战，段落 xin-wudaishi-b08f244b9241-p003145；仅作946年死亡记载的时序异说校核，不提前录入后续战事；纸本及异文待核。", "id": "a90839a2-9053-5777-b22f-e70b09603b35"}, {"title": "旧五代史·卷102·隐帝本纪·乾祐二年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7852147b76d0b357a666a03e1c8d219918bae3dc/content/books/zizhi-tongjian/vol-288/year-0949/part-05/sources/library/jiuwudaishi-102-october-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年十月，段落 jiu-wudaishi-205deb4a7860-p002478；已核上下文及传主，纸本及异文待核。", "id": "c13a4bc7-de91-5a2b-87ce-68d6b3bd4dcf"}, {"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44b0593aeab837b5fbc1263a74f880f3ba1b4acb/content/books/zizhi-tongjian/vol-287/year-0947/part-04/sources/library/jiuwudaishi-100-july-transfers/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002436；EPUB电子本，纸本及异文待核", "id": "730295ed-42b9-5013-95c3-02b9a659dd24"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "查文徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "休宁人，南唐官员。943年李璟即位后，史书记他与陈觉、冯延巳、冯延鲁、魏岑互相引荐，不久与魏岑同任枢密副使。当时五人被称为五鬼，称呼按史书记载保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "b0abcb8a-3aa7-5d58-8f3c-79f4fc15b117"}, {"name": "陈诲", "aliases": ["陳誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建安人，王延政麾下战棹都头。940年三月在夜袭中杀死潘师逵。生卒年未载。", "biography": null, "status": "draft", "id": "8c18058e-c4f8-52ab-a4d2-9caaba34336a"}, {"name": "马先进", "aliases": ["馬先進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "福州将领。950年南唐进军福州时被陈诲俘获。《资治通鉴》把被俘记在查文徽到达福州之前；《新五代史》叙在查文徽被俘之后，还记李璟把他送回吴越。时序差异保留。生卒年未载。", "biography": null, "status": "draft", "id": "ae093500-71f0-5c78-bc13-e94eb49ccb1c"}, {"name": "吴程", "aliases": ["吳程"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "山阴人，吴越丞相。947年十二月鲍修让将李仁达首级送到钱塘后，钱弘倧任吴程主持威武节度事务。生卒年未载。", "biography": null, "status": "draft", "id": "70950e94-6804-5b3e-afb7-43c0ab271dea"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "刘审交", "aliases": ["劉審交"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字求益，幽州文安人。947年萧翰在汴州时重新任用他为三司使。萧翰北归后，他反对闭城拒守，主张听从王淑妃的迎接刘知远方案。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9999edd0-1ba8-57b3-92d5-504e71c4f459"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "杜建徽", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：杜建徽。", "biography": null, "status": "draft", "id": "dc45e504-5420-5b40-bf71-bba443a606f4"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "常思", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉昭义节度使。948年讨伐李守贞等三镇时曾驻潼关，后来与郭威、白文珂、刘词分三路进攻河中。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "1d3a1e89-5826-52d4-ba66-55dbc3d91e22"}, {"name": "杨承信", "aliases": ["楊承信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。《资治通鉴》称他为次子，938年五月与杨承祚同获优厚任官，具体官名未载。", "biography": null, "status": "draft", "id": "70bde002-fc6d-5293-9fb1-214458b656a6"}, {"name": "薛怀让", "aliases": ["薛懷讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋怀州刺史。944年二月乙巳与李守贞、皇甫遇、梁汉璋等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f1bb0fbd-9418-522b-b292-28446544ad7f"}, {"name": "武行德", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州榆次人。947年受契丹命运送晋朝铠甲兵器，途中与军士夺取兵器、杀契丹监军，继而占据河阳。生卒年尚未录入。", "biography": null, "status": "draft", "id": "e0ed92f8-edb4-574b-83af-85088429a093"}, {"name": "郭谨", "aliases": ["郭謹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋侍卫步军都指挥使。943年十一月壬寅奉命率兵驻守郓州。生卒年未载。", "biography": null, "status": "draft", "id": "0269eda3-2432-50c2-990e-2ec09ead5f82"}, {"name": "王饶", "aliases": ["王饒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国左厢都指挥使。946年十月辛未，石重贵任命他为北征军的步军右厢都指挥使。《旧五代史》卷85记有相同部署。生卒年及籍贯未载。", "biography": null, "status": "draft", "id": "0da0dd37-babc-548d-b33d-f587847464ed"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

