SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "郭威从北方巡边返回", "start_year": 950, "end_year": 950, "time_original": "950年二月甲申", "dynasty": "五代十国", "description": "郭威从北方巡边返回。", "phases": [], "location_name": "后汉北部边境及朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7f0a0dfe-d129-5ef2-b39b-aa19744d0402"}, {"title": "福州来人声称吴越军已离城，邀请查文徽主持福州", "start_year": 950, "end_year": 950, "time_original": "950年二月条下，查文徽进军福州以前，具体日未载", "dynasty": "五代十国", "description": "福州来人声称吴越军已离城，邀请查文徽主持福州。", "phases": [], "location_name": "建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5a638a09-3c35-5fc7-b3ba-7f6bc40a58c7"}, {"title": "查文徽相信来人，派陈诲率水军沿闽江进军", "start_year": 950, "end_year": 950, "time_original": "950年二月条下，查文徽到达福州以前，具体出发日未载", "dynasty": "五代十国", "description": "查文徽相信来人，派陈诲率水军沿闽江进军。", "phases": [], "location_name": "建州、闽江", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a2b92e35-0aaa-5f19-be0f-6682d8e8d563"}, {"title": "陈诲水军抵达福州城下，击败守军并俘获马先进", "start_year": 950, "end_year": 950, "time_original": "950年二月条下，查文徽庚寅到达福州之前", "dynasty": "五代十国", "description": "《资治通鉴》记大雨水涨，陈诲一夜行七百里，到福州城下击败守军，俘获马先进等将领。", "phases": [], "location_name": "闽江、福州城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dacb7142-c7ee-5760-9d27-c4bdda12c008"}, {"title": "查文徽抵达福州，吴程派数百人假意迎接", "start_year": 950, "end